import math,random
random.seed(7)
def spark(vals,w,h,color='var(--jade)',fill=True,sw=2):
    mx=max(vals);mn=min(vals);n=len(vals)
    pts=[(i*w/(n-1),h-4-(v-mn)/(mx-mn+1e-9)*(h-10)) for i,v in enumerate(vals)]
    d='M'+' L'.join(f'{x:.1f},{y:.1f}' for x,y in pts)
    f=f'<path d="{d} L{w},{h} L0,{h} Z" fill="{color}" opacity=".12"/>' if fill else ''
    return f'<svg viewBox="0 0 {w} {h}" width="100%" height="{h}" preserveAspectRatio="none">{f}<path class="draw" pathLength="1" d="{d}" fill="none" stroke="{color}" stroke-width="{sw}" vector-effect="non-scaling-stroke"/></svg>'
def series(n,base,amp,trend=0):
    return [base+amp*math.sin(i/2.3)+random.uniform(-amp*.5,amp*.5)+trend*i for i in range(n)]
def trend_chart(w=860,h=240):
    a=series(30,4200,700,40);b=series(30,3600,600,20)
    mx=max(a)*1.1
    def path(v): return 'M'+' L'.join(f'{40+i*(w-50)/29:.1f},{h-28-x/mx*(h-50):.1f}' for i,x in enumerate(v))
    grid=''.join(f'<line x1="40" x2="{w-10}" y1="{h-28-k*(h-50)/4:.0f}" y2="{h-28-k*(h-50)/4:.0f}" class="grid"/><text x="34" y="{h-24-k*(h-50)/4:.0f}" class="ax" text-anchor="end">{int(mx*k/4/1000*10)/10}k</text>' for k in range(5))
    xl=''.join(f'<text x="{40+i*(w-50)/29:.0f}" y="{h-8}" class="ax" text-anchor="middle">9/{17+i if 17+i<=30 else i-13}</text>' for i in range(0,30,4))
    pa=path(a)
    ann=f'<line x1="{40+18*(w-50)/29:.0f}" x2="{40+18*(w-50)/29:.0f}" y1="14" y2="{h-28}" stroke="var(--gold)" stroke-dasharray="3 3"/><rect x="{40+18*(w-50)/29-38:.0f}" y="4" width="76" height="18" rx="9" fill="var(--gold)"/><text x="{40+18*(w-50)/29:.0f}" y="17" text-anchor="middle" font-size="11" fill="#fff">10/5 新版上线</text>'
    import json
    return f'<svg class="trend" data-w="{w}" data-h="{h}" data-mx="{mx:.0f}" data-a="{json.dumps([int(x) for x in a])}" data-b="{json.dumps([int(x) for x in b])}" viewBox="0 0 {w} {h}" width="100%" height="{h}">{grid}{xl}<path d="{pa} L{w-10},{h-28} L40,{h-28}Z" fill="url(#gj)" /><path d="{pa}" class="l1 draw" pathLength="1"/><path d="{path(b)}" class="l2 draw" pathLength="1"/><path d="{'M'+' L'.join(f'{40+i*(w-50)/29:.1f},{h-28-x/mx*(h-50):.1f}' for i,x in list(enumerate(a))[27:])}" class="l3"/>{ann}<g class="xh"><line class="xhl" x1="{40+24*(w-50)/29:.0f}" x2="{40+24*(w-50)/29:.0f}" y1="14" y2="{h-28}"/><circle class="xhc" cx="{40+24*(w-50)/29:.0f}" cy="{h-28-a[24]/mx*(h-50):.0f}" r="5" fill="var(--bg2)" stroke="var(--jade)" stroke-width="2.5"/><g transform="translate({40+24*(w-50)/29-70:.0f},{h-28-a[24]/mx*(h-50)-70:.0f})"><rect width="140" height="54" rx="8" class="tip"/><text x="10" y="18" class="tipt t1">10/11 周日</text><text x="10" y="36" class="tipv t2">浏览 {int(a[24]):,}</text><text x="10" y="49" class="tipt t3">上期 {int(b[24]):,} · +12.4%</text></g></g><rect class="hit" x="40" y="0" width="{w-50}" height="{h-28}" fill="transparent"/></svg>'
def bars(rows,unit=''):
    m=max(r[1] for r in rows)
    return ''.join(f'<div class="bar"><span class="bl">{r[0]}</span><span class="bv">{r[1]:,}{unit}</span><span class="fx">⊕ 筛选</span><i style="width:{r[1]/m*100:.0f}%"></i></div>' for r in rows)
def donut(parts,size=150):
    tot=sum(p[1] for p in parts);acc=0;r=54;c=2*math.pi*r;s=''
    cols=['var(--jade)','var(--gold)','var(--ink3)','var(--cinnabar)','var(--mist)']
    for i,p in enumerate(parts):
        l=p[1]/tot*c;s+=f'<circle r="{r}" cx="75" cy="75" fill="none" stroke="{cols[i]}" stroke-width="18" stroke-dasharray="{l:.1f} {c:.1f}" stroke-dashoffset="{-acc:.1f}" transform="rotate(-90 75 75)"/>';acc+=l
    leg=''.join(f'<li><b style="background:{cols[i]}"></b>{p[0]}<em>{p[1]/tot*100:.1f}%</em></li>' for i,p in enumerate(parts))
    return f'<div class="donut"><svg width="{size}" height="{size}" viewBox="0 0 150 150">{s}<text x="75" y="72" text-anchor="middle" class="dn">{tot:,}</text><text x="75" y="92" text-anchor="middle" class="ax">访客</text></svg><ul>{leg}</ul></div>'
def heat():
    days='一二三四五六日';s=''
    for d in range(7):
        s+=f'<text x="0" y="{d*16+12}" class="ax">{days[d]}</text>'
        for h in range(24):
            v=max(0,min(1,.25+.6*math.sin((h-6)/24*math.pi)*(1 if d<5 else .7)+random.uniform(-.15,.15)))
            s+=f'<rect x="{18+h*15}" y="{d*16}" width="13" height="13" rx="3" fill="var(--jade)" opacity="{.08+v*.9:.2f}"/>'
    return f'<svg viewBox="0 0 380 115" width="100%">{s}</svg>'
