def topbar(title,sub=''):
    return f'<header class="top"><div><h1>{title}</h1><p>{sub}</p></div><div class="tools"><div class="seg"><span>今天</span><span>7 天</span><span class="on">30 天</span><span>自定义</span></div><div class="date"><span class="dr">2026-09-17 → 2026-10-16</span> <label class="sw"><input type="checkbox" checked/><i></i>对比上期</label></div><button class="ghost">＋ 筛选</button><span class="kbd">⌘K</span><button class="ghost icon themebtn" title="切换深浅色">◑</button></div></header>'
